import java.text.Normalizer;
import java.util.Arrays;
import java.util.List;
import java.util.Set;
import java.util.regex.Pattern;

/**
 * A filter over the customer list: a name search and a set of statuses.
 *
 * <p>A customer matches when it satisfies both parts. The name part splits
 * {@link #name} on whitespace into terms, of which every term must appear as
 * a substring of the customer's first or last name; matching ignores case and
 * accents. The status part matches every status when {@link #statuses} is
 * empty, and only the given statuses otherwise.
 */
public record CustomerFilter(String name, Set<CustomerStatus> statuses) {

    public static final CustomerFilter EMPTY = new CustomerFilter("", Set.of());

    private static final Pattern DIACRITICS = Pattern.compile("\\p{M}+");

    public CustomerFilter {
        name = name == null ? "" : name;
        statuses = statuses == null ? Set.of() : Set.copyOf(statuses);
    }

    /** Lower-cases and strips accents, so matching is both case- and accent-insensitive. */
    static String normalize(String value) {
        String decomposed = Normalizer.normalize(value, Normalizer.Form.NFD);
        return DIACRITICS.matcher(decomposed).replaceAll("").toLowerCase();
    }

    /** The name filter split into normalized, non-empty search terms. */
    public List<String> nameTerms() {
        String trimmed = name.trim();
        if (trimmed.isEmpty()) {
            return List.of();
        }
        return Arrays.asList(normalize(trimmed).split("\\s+"));
    }

    /** Whether the given customer satisfies both the name and the status filter. */
    public boolean matches(Customer customer) {
        if (!statuses.isEmpty() && !statuses.contains(customer.status())) {
            return false;
        }
        List<String> terms = nameTerms();
        if (terms.isEmpty()) {
            return true;
        }
        String firstName = normalize(customer.firstName());
        String lastName = normalize(customer.lastName());
        return terms.stream().allMatch(term -> firstName.contains(term) || lastName.contains(term));
    }
}
