+    void typingNarrowsTheGridWithoutOneQueryPerKeystroke() {
+        TextFieldElement nameFilter = new TextFieldElement(page.locator("vaadin-text-field"));
+        GridElement grid = GridElement.get(page);
+        int initialTotal = grid.getTotalRowCount();
+
+        int pageQueriesBefore = queryLog.pageQueries().size();
+        // A nine-letter word, typed one key at a time like a real user.
+        nameFilter.getInputLocator().pressSequentially("josephine",
+                new Locator.PressSequentiallyOptions().setDelay(60));
+
+        page.waitForCondition(() -> grid.getTotalRowCount() != initialTotal,
+                new Page.WaitForConditionOptions().setTimeout(5000));
+
+        int pageQueriesAfter = queryLog.pageQueries().size();
+        int keystrokes = "josephine".length();
+        assertTrue(pageQueriesAfter - pageQueriesBefore < keystrokes,
+                "Expected far fewer than " + keystrokes + " page queries from typing, got "
+                        + (pageQueriesAfter - pageQueriesBefore));
+        assertTrue(pageQueriesAfter - pageQueriesBefore <= 2,
+                "Expected typing to settle into one or two queries, got "
+                        + (pageQueriesAfter - pageQueriesBefore));
+
+        int narrowedTotal = grid.getTotalRowCount();
+        assertTrue(narrowedTotal > 0 && narrowedTotal < initialTotal);
+    }
+
+    @Test
+    void filterChangesUpdateTheAddressBarWithoutPushingHistory() {
+        int historyLengthBefore = (int) (Object) page.evaluate("() => window.history.length");
+
+        TextFieldElement nameFilter = new TextFieldElement(page.locator("vaadin-text-field"));
+        nameFilter.getInputLocator().pressSequentially("aal",
+                new Locator.PressSequentiallyOptions().setDelay(60));
+        page.waitForURL(url -> url.contains("name=aal"),
+                new Page.WaitForURLOptions().setTimeout(5000));
+        assertTrue(page.url().contains("name=aal"));
+
+        MultiSelectComboBoxElement statusFilter =
+                MultiSelectComboBoxElement.getByLabel(page, "Status");
+        statusFilter.selectItem("ACTIVE");
+        page.waitForURL(url -> url.contains("status=ACTIVE"),
+                new Page.WaitForURLOptions().setTimeout(5000));
+        assertTrue(page.url().contains("name=aal"));
+        assertTrue(page.url().contains("status=ACTIVE"));
+
+        int historyLengthAfter = (int) (Object) page.evaluate("() => window.history.length");
+        assertEquals(historyLengthBefore, historyLengthAfter,
+                "Filtering must not push new history entries");
+
+        statusFilter.deselectItem("ACTIVE");
+        page.waitForCondition(() -> !page.url().contains("status="),
+                new Page.WaitForConditionOptions().setTimeout(5000));
+        nameFilter.clear();
+        page.waitForCondition(() -> !page.url().contains("name="),
+                new Page.WaitForConditionOptions().setTimeout(5000));
+        assertTrue(page.url().endsWith("/") || page.url().endsWith(String.valueOf(port)));
+    }
+
+    @Test
+    void openingAUrlWithParametersAppliesAndDisplaysTheFilter() {
+        page.navigate(getUrl() + "?name=aal&status=ACTIVE,CLOSED");
+        page.waitForCondition(() -> "aal".equals(new TextFieldElement(page.locator("vaadin-text-field")).getValue()),
+                new Page.WaitForConditionOptions().setTimeout(5000));
+
+        TextFieldElement nameFilter = new TextFieldElement(page.locator("vaadin-text-field"));
+        assertEquals("aal", nameFilter.getValue());
+
+        MultiSelectComboBoxElement statusFilter =
+                MultiSelectComboBoxElement.getByLabel(page, "Status");
+        assertEquals(2, statusFilter.getSelectedItemCount());
+
+        GridElement grid = GridElement.get(page);
+        assertTrue(grid.getTotalRowCount() > 0 && grid.getTotalRowCount() < 500);
+    }
+}
